import{_ as t}from"./chunks/tableau.CZ_ooqZJ.js";import{_ as a,o as s,c as r,a2 as n}from"./chunks/framework.CQxpk36T.js";const m=JSON.parse('{"title":"Le tableau de bord","description":"","frontmatter":{},"headers":[],"relativePath":"home-assistant/tableau.md","filePath":"home-assistant/tableau.md","lastUpdated":1793563901000}'),o={name:"home-assistant/tableau.md"};function i(d,e,l,u,p,c){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="le-tableau-de-bord" tabindex="-1">Le tableau de bord <a class="header-anchor" href="#le-tableau-de-bord" aria-label="Permalink to &quot;Le tableau de bord&quot;">​</a></h1><p>L&#39;onglet <strong>Tableau</strong> range chaque appareil dans une tuile faite pour lui, avec un petit dessin qui montre son état. Les tuiles sont rangées <strong>par bâtiment, puis par pièce</strong>, dans l&#39;ordre de <code>propriete.ts</code>.</p><p><img src="'+t+'" alt="Le tableau de bord de la maison d&#39;exemple"></p><h2 id="les-tuiles" tabindex="-1">Les tuiles <a class="header-anchor" href="#les-tuiles" aria-label="Permalink to &quot;Les tuiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Appareil</th><th>Tuile</th><th>Toucher</th><th>Détail (appui long)</th></tr></thead><tbody><tr><td>Lumière</td><td>Lampe qui rayonne, curseur d&#39;intensité</td><td>Allume, éteint</td><td>Intensité, teinte (température de couleur)</td></tr><tr><td>Interrupteur, prise, ventilateur</td><td>Arrêt / Marche</td><td>Bascule</td><td></td></tr><tr><td>Volet roulant</td><td>Tablier qui descend</td><td>▲ ■ ▼</td><td>Position</td></tr><tr><td>Porte de garage, portail</td><td>Porte qui monte</td><td>Ouvrir / Fermer / Arrêter</td><td></td></tr><tr><td>Thermostat</td><td>Cadran</td><td></td><td>Glisser la poignée ou − / +, modes, préréglages</td></tr></tbody></table><p>Les <strong>capteurs</strong> (température, humidité, puissance, ouvertures) s&#39;affichent en pastilles dans le titre de leur pièce.</p><h2 id="gestes" tabindex="-1">Gestes <a class="header-anchor" href="#gestes" aria-label="Permalink to &quot;Gestes&quot;">​</a></h2><ul><li><strong>Toucher</strong> une tuile l&#39;actionne.</li><li><strong>Glisser</strong> le curseur d&#39;une lampe règle son intensité : la lampe suit pendant le glissé, sans attendre qu&#39;on lâche.</li><li><strong>Appui long</strong> (ou clic droit) ouvre le détail : intensité, position, mode, et <strong>Épingler</strong> en favori.</li></ul><p>Tant que l&#39;appareil n&#39;a pas répondu à un ordre, son dessin <strong>pulse</strong>.</p><h2 id="favoris-scenes-recherche" tabindex="-1">Favoris, scènes, recherche <a class="header-anchor" href="#favoris-scenes-recherche" aria-label="Permalink to &quot;Favoris, scènes, recherche&quot;">​</a></h2><ul><li>Les <strong>favoris</strong> passent en tête du tableau.</li><li>Les <strong>scènes</strong> et <strong>scripts</strong> de Home Assistant forment une rangée de boutons.</li><li>La <strong>recherche</strong> trouve un appareil par son nom, sa pièce ou son bâtiment, sans se soucier des accents ni des majuscules.</li></ul><h2 id="ce-qui-n-apparait-pas" tabindex="-1">Ce qui n&#39;apparaît pas <a class="header-anchor" href="#ce-qui-n-apparait-pas" aria-label="Permalink to &quot;Ce qui n&#39;apparaît pas&quot;">​</a></h2><p>Seuls les appareils <strong>rangés dans une Zone</strong> ont une tuile : Home Assistant en compte souvent des centaines. Les entités de configuration, de diagnostic et les entités masquées sont écartées. Les Zones sans pièce dans <code>propriete.ts</code> (jardin, terrasse) sont regroupées dans la rubrique <strong>Extérieur</strong>.</p>',13)])])}const b=a(o,[["render",i]]);export{m as __pageData,b as default};
